# -*- coding: utf-8 -*-
"""kb_serve.py — 常驻检索服务（消除每次查询的固定启动开销）。

为什么必须要有它
----------------
2026-10-04 实测（583 页规模）：

| 环节 | 耗时 |
|---|---|
| BM25 打分（倒排索引） | **0.39 ms** |
| 语义检索的向量点积 | **0.17 ms** |
| `import sentence_transformers` | 8.3 s |
| 加载 text2vec-base-chinese 模型 | 12.9 s |
| jieba 词典加载 | 0.53 s |

⇒ **真正的计算是亚毫秒级，99.9% 的时间花在每次进程启动都重做一遍的初始化上。**
CLI 模式下语义检索 **30.2 s/次**、混合检索 **56.0 s/次**。
而 CLAUDE.md 的 Agentic RAG 协议要求「查询分解 + 多跳推理 + 多源交叉比对」，
一次回答需 5–20 次检索 ⇒ 纯等待 5–19 分钟。**协议写得再细也跑不动。**

本服务把索引与模型**只加载一次**，之后每次查询毫秒级返回。

设计约束
--------
· **只用标准库**（http.server / json / urllib），不引入任何新依赖。
· **用 127.0.0.1 上的 HTTP，不用命名管道**——当前沙箱下程序无法打开命名管道。
· **只监听回环地址**，不对外暴露。
· 索引/模型惰性加载：首次请求付一次成本，之后常驻。

用法
----
    python tools/kb_serve.py --port 8791            # 前台常驻（可放后台跑）
    python tools/kb_serve.py --port 8791 --warm     # 启动时预热语义模型
    python tools/kb_serve.py --status               # 查服务状态
    python tools/kb_serve.py --stop                 # 停止
    python tools/kb_serve.py --selftest             # 自检

接口（GET，返回 JSON）
    /health                                   服务与索引状态
    /search?q=...&k=10&type=concept,entity&mode=bm25|semantic|hybrid
    /resolve?q=...
    /stats
"""

import os
import io
import sys
import json
import time
import argparse
import threading
import urllib.request
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K

DEFAULT_PORT = 8791
_START = time.time()
_LOCK = threading.Lock()          # 模型推理串行化（torch 在小机器上并发不划算）
_STATE = {"meta": None, "bm": None, "sem": None, "warm": False,
          "warm_error": None, "queries": 0}


# ---------------------------------------------------------------- 惰性加载

def get_index():
    if _STATE["meta"] is None or _STATE["bm"] is None:
        import kb_search as KS
        meta, bm = KS.load_index()
        _STATE["meta"], _STATE["bm"] = meta, bm
    return _STATE["meta"], _STATE["bm"]


def get_semantic():
    if _STATE["sem"] is None:
        import kb_semantic_search as SEM
        _STATE["sem"] = SEM
    return _STATE["sem"]


def warm_semantic():
    """预热：加载模型 + 校验索引新鲜度。放进后台线程，不阻塞服务起来。"""
    try:
        SEM = get_semantic()
        SEM.semantic_search("预热", top_k=1)
        _STATE["warm"] = True
    except Exception as e:                       # noqa: BLE001
        _STATE["warm_error"] = f"{type(e).__name__}: {e}"


# ---------------------------------------------------------------- 检索逻辑

def do_search(q, k=10, type_filter="", mode="bm25", as_json=True):
    import kb_search as KS
    meta, bm = get_index()
    types = [t.strip() for t in (type_filter or "").split(",") if t.strip()]

    def keep(name, ptype):
        return (not types) or (ptype in types)

    results = []
    if mode in ("semantic", "hybrid"):
        SEM = get_semantic()
        with _LOCK:
            if mode == "semantic":
                raw = SEM.semantic_search(q, top_k=k * 3)
            else:
                raw = SEM.hybrid_search(q, top_k=k * 3)
        for name, score in raw:
            s, u, tags, al, t = KS.meta_of(meta, name)
            if keep(name, t):
                results.append((name, score, s, u, tags, al, t))
        results = results[:k]
    else:
        alias_hits = KS.resolve_aliases(q, meta.get("alias_map", {}))
        strong = [(a, c) for a, c in alias_hits if len(a) >= 3] or alias_hits[:1]
        canon = [c for _, c in strong]
        qt = K.tokenize(q)
        for c in canon:
            qt.extend(K.tokenize(c))
        for a, c in alias_hits:
            if c not in canon:
                qt.extend(K.tokenize(c))
        with _LOCK:
            ranked = KS.bm25_score(qt, bm, canon, query_raw=q)
        for name, score in ranked:
            s, u, tags, al, t = KS.meta_of(meta, name)
            if keep(name, t):
                results.append((name, score, s, u, tags, al, t))
        results = results[:k]

    out = [{"name": n, "type": t, "score": round(sc, 4), "summary": s,
            "updated": u, "tags": tags, "aliases": al, "path": KS.page_path(n, t)}
           for n, sc, s, u, tags, al, t in results]
    _STATE["queries"] += 1
    return {"mode": mode, "query": q, "count": len(out), "results": out}


def do_resolve(q):
    import kb_search as KS
    meta, _ = get_index()
    return {"query": q, "alias_hits": KS.resolve_aliases(q, meta.get("alias_map", {}))}


def do_corpus(q, k=8):
    """raw 全文分块检索（首次调用会加载 100+ MB 语料索引，之后常驻）。"""
    import kb_corpus as C
    with _LOCK:
        res = C.search(q, k=k)
    _STATE["queries"] += 1
    return {"mode": "corpus", "query": q, "count": len(res), "results": res}


def do_route(q, budget=None, layers=(1, 2, 3)):
    """分层检索路由：L1 综合 / L2 文献卡 / L3 原文块。"""
    import kb_route as R
    with _LOCK:
        pkg = R.route(q, budget=budget, layers=layers)
    _STATE["queries"] += 1
    return pkg


def do_health():
    meta, bm = get_index()
    sem_info = {}
    try:
        SEM = get_semantic()
        sem_info["embed_index"] = os.path.exists(SEM.EMBED_PATH)
        sem_info["warm"] = _STATE["warm"]
        if _STATE["warm_error"]:
            sem_info["warm_error"] = _STATE["warm_error"]
    except Exception as e:                       # noqa: BLE001
        sem_info["error"] = str(e)
    try:
        import kb_corpus as C
        meta_p = C.META_PATH
        if os.path.exists(meta_p):
            with open(meta_p, encoding="utf-8") as f:
                cm = json.load(f)
            sem_info["corpus_chunks"] = cm.get("chunks")
            sem_info["corpus_files"] = cm.get("files")
            sem_info["corpus_loaded"] = bool(C._CACHE)
    except Exception:                            # noqa: BLE001
        pass
    return {
        "ok": True,
        "uptime_s": round(time.time() - _START, 1),
        "pid": os.getpid(),
        "pages": meta.get("count"),
        "bm25_version": bm.get("_version", 1),
        "bm25_postings": sum(len(v) for v in (bm.get("postings") or {}).values()),
        "queries_served": _STATE["queries"],
        "semantic": sem_info,
    }


# ---------------------------------------------------------------- HTTP

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):           # 静音默认访问日志
        pass

    def _send(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        qs = urllib.parse.parse_qs(parsed.query)
        try:
            if path == "/shutdown":
                # 让 --stop 可靠工作（此前 /shutdown 未实现，--stop 只能靠 taskkill 兜底且并不总成功）
                self._send({"ok": True, "bye": True})
                threading.Thread(target=self.server.shutdown, daemon=True).start()
                return
            if path == "/health":
                return self._send(do_health())
            if path == "/stats":
                meta, bm = get_index()
                return self._send({
                    "pages": meta.get("count"),
                    "alias_entries": len(meta.get("alias_map", {})),
                    "vocab": len(bm.get("df", {})),
                    "n_docs": bm.get("n_docs"),
                    "bm25_version": bm.get("_version", 1),
                })
            if path == "/resolve":
                return self._send(do_resolve(qs.get("q", [""])[0]))
            if path == "/corpus":
                q = qs.get("q", [""])[0]
                if not q.strip():
                    return self._send({"error": "missing q"}, 400)
                return self._send(do_corpus(q, k=int(qs.get("k", ["8"])[0])))
            if path == "/route":
                q = qs.get("q", [""])[0]
                if not q.strip():
                    return self._send({"error": "missing q"}, 400)
                # 解析走 kb_lib 的单一实现（此前 HTTP 查询串与 CLI 各有一套拷贝）。
                layers = K.parse_layers(qs.get("layer", [""])[0])
                budget = K.parse_budget(qs.get("budget", [""])[0])
                return self._send(do_route(q, budget=budget, layers=layers))
            if path == "/search":
                q = qs.get("q", [""])[0]
                if not q.strip():
                    return self._send({"error": "missing q"}, 400)
                return self._send(do_search(
                    q,
                    k=int(qs.get("k", ["10"])[0]),
                    type_filter=qs.get("type", [""])[0],
                    mode=qs.get("mode", ["bm25"])[0],
                ))
            return self._send({"error": "unknown endpoint",
                               "endpoints": ["/health", "/stats", "/resolve",
                                             "/search", "/corpus", "/route"]}, 404)
        except Exception as e:                   # noqa: BLE001
            return self._send({"error": f"{type(e).__name__}: {e}"}, 500)


# ---------------------------------------------------------------- 客户端

def server_url(port=DEFAULT_PORT):
    return f"http://127.0.0.1:{port}"


def ping(port=DEFAULT_PORT, timeout=1.5):
    try:
        with urllib.request.urlopen(server_url(port) + "/health", timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except Exception:                            # noqa: BLE001
        return None


def request(path, port=DEFAULT_PORT, timeout=30):
    with urllib.request.urlopen(server_url(port) + path, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description="常驻检索服务")
    ap.add_argument("--port", type=int, default=DEFAULT_PORT)
    ap.add_argument("--warm", action="store_true", help="启动时后台预热语义模型")
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--stop", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    if args.status:
        h = ping(args.port)
        print(json.dumps(h, ensure_ascii=False, indent=1) if h
              else f"[--] 服务未运行（{server_url(args.port)}）")
        return 0 if h else 1
    if args.stop:
        h = ping(args.port)
        if not h:
            print("[--] 服务未运行")
            return 0
        try:
            with urllib.request.urlopen(
                    server_url(args.port) + "/shutdown", timeout=3):
                pass
        except Exception:                        # noqa: BLE001
            pass
        # /shutdown 未实现时按 pid 结束
        time.sleep(0.3)
        if ping(args.port):
            try:
                import subprocess
                subprocess.run(["taskkill", "/PID", str(h["pid"]), "/F"],
                               capture_output=True)
            except Exception:                    # noqa: BLE001
                pass
        print("[ok] 已停止" if not ping(args.port) else "[!] 停止失败")
        return 0

    # 先加载索引（快），模型可后台预热
    meta, bm = get_index()
    srv = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    print(f"[ok] 常驻检索服务已启动  {server_url(args.port)}")
    print(f"     pid={os.getpid()}  页面 {meta.get('count')}  "
          f"词表 {len(bm.get('df', {}))}  bm25 v{bm.get('_version', 1)}")
    print(f"     接口: /health  /stats  /resolve?q=  "
          f"/search?q=&k=10&mode=bm25|semantic|hybrid")
    print(f"           /corpus?q=&k=8        raw 全文分块检索")
    print(f"           /route?q=&budget=5,5,8  分层上下文包（L1综合/L2文献卡/L3原文）")
    if args.warm:
        threading.Thread(target=warm_semantic, daemon=True).start()
        print("     [warm] 语义模型后台预热中…（首次语义查询无需再等 21 秒）")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\n[ok] 服务已停止")
    return 0


def selftest():
    """自检：索引可加载、打分路径可跑通、路径合法。"""
    print("=== kb_serve --selftest ===")
    ok = True
    meta, bm = get_index()
    print(f"  索引: {meta.get('count')} 页, bm25 v{bm.get('_version', 1)}")
    if bm.get("_version") != 2:
        print("  [!] 索引不是 v2（缺 postings），语义/混合以外的路径仍可用")
    r = do_search("固态电解质界面", k=3)
    print(f"  BM25 检索返回 {r['count']} 条")
    # 「必须召回」只对**有内容**的库成立；空库 0 命中是正确行为，不是故障。
    if meta.get("count", 0) > 0:
        ok = ok and r["count"] > 0
    else:
        print("  [skip] 空库：无内容可召回（检索路径已跑通）")
    for item in r["results"]:
        p = item["path"]
        ex = os.path.exists(os.path.join(K.VAULT, p))
        print(f"    [{'ok' if ex else 'FAIL'}] {item['name'][:28]} -> {p}")
        ok = ok and ex
    print(f"  /resolve: {do_resolve('SSE')['alias_hits'][:2]}")
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    sys.exit(main())
